class Solution {
public:
    ListNode* mergeNodes(ListNode* head) {
        ListNode* tail = head;
        ListNode* cur = head->next;
        int sum = 0;
        while (cur) {
            if (cur->val == 0) {
                tail->next = cur;
                tail = cur;
                tail->val = sum;
                sum = 0;
            } else {
                sum += cur->val;
            }
            cur = cur->next;
        }
        return head->next;
    }
};
